1	// QEMU TCG plugin: drains architectural state and exits when the guest
2	// executes the ROI enter marker `slti x0, x0, 0x5A0` (a HINT NOP). Shares
3	// hybrid/insn_match.h and hybrid/state_abi.h with the vsim side.
4	
5	#include "hybrid/handoff_site.h"
6	#include "hybrid/insn_match.h"
7	#include "hybrid/reg_names.h"
8	#include "hybrid/state_abi.h"
9	#include "hybrid/v_drain_policy.h"
10	
11	#include <qemu-plugin.h>
12	
13	#include <glib.h>
14	
15	#include <fcntl.h>
16	#include <inttypes.h>
17	#include <stddef.h>
18	#include <stdint.h>
19	#include <stdio.h>
20	#include <stdlib.h>
21	#include <string.h>
22	#include <unistd.h>
23	#include <limits.h>
24	
25	QEMU_PLUGIN_EXPORT int qemu_plugin_version = QEMU_PLUGIN_VERSION;
26	
27	typedef struct {
28	    struct qemu_plugin_register *gpr[32];
29	    struct qemu_plugin_register *fpr[32];
30	    struct qemu_plugin_register *fcsr;  // L20: frm[7:5] | fflags[4:0]
31	    struct qemu_plugin_register *pc;
32	    struct qemu_plugin_register *priv;  // L6: gdbstub virtual feature
33	
34	    // M-mode CSRs as exposed by QEMU's gdbstub csr feature.
35	    struct qemu_plugin_register *mstatus;
36	    struct qemu_plugin_register *mepc;
37	    struct qemu_plugin_register *mtvec;
38	    struct qemu_plugin_register *mcause;
39	    struct qemu_plugin_register *mtval;
40	    struct qemu_plugin_register *mscratch;
41	    struct qemu_plugin_register *medeleg;
42	    struct qemu_plugin_register *mideleg;
43	    struct qemu_plugin_register *mip;
44	    struct qemu_plugin_register *mie;
45	    struct qemu_plugin_register *mcycle;
46	    struct qemu_plugin_register *minstret;
47	    struct qemu_plugin_register *satp;
48	
49	    // Andes custom machine setup CSRs (crt0 writes these at boot). mcache_ctl
50	    // enables the L1 caches; without transporting it the cycle engine resumes
51	    // with caches off. Absent on non-Andes stubs -> NULL handle -> drains 0.
52	    struct qemu_plugin_register *mcache_ctl;
53	    struct qemu_plugin_register *mmisc_ctl;
54	
55	    // Andes V5 CSR block (v3). HYBRID_ANDES_CSR_LIST is the shared source of
56	    // truth; a NULL handle (non-Andes stub) drains 0 -> tolerant no-op.
57	#define HYBRID_ANDES_FIELD(field, addr, name) \
58	    struct qemu_plugin_register *andes_##field;
59	    HYBRID_ANDES_CSR_LIST(HYBRID_ANDES_FIELD)
60	#undef HYBRID_ANDES_FIELD
61	    struct qemu_plugin_register *pmacfg[HYBRID_PMA_CFG_NUM];
62	    struct qemu_plugin_register *pmaaddr[HYBRID_PMA_ADDR_NUM];
63	
64	    struct qemu_plugin_register *pmpcfg[HYBRID_PMP_CFG_NUM];
65	    struct qemu_plugin_register *pmpaddr[HYBRID_PMP_ADDR_NUM];
66	
67	    struct qemu_plugin_register *vstart;
68	    struct qemu_plugin_register *vxsat;
69	    struct qemu_plugin_register *vxrm;
70	    struct qemu_plugin_register *vcsr;
71	    struct qemu_plugin_register *vtype;
72	    struct qemu_plugin_register *vl;
73	    struct qemu_plugin_register *vlenb;
74	    struct qemu_plugin_register *vreg[32];
75	} VcpuRegs;
76	
77	static struct qemu_plugin_scoreboard *vcpu_state;
78	static char *outfile_path;
79	
80	// PC-trigger mode: when enter_pc_arg is non-zero (set via plugin arg
81	// `enter_pc=0x...`), the CSR-insn matcher is bypassed entirely and the
82	// drain callback is registered only for instructions whose vaddr equals
83	// enter_pc_arg. The kind reported on the drain is HYBRID_HANDOFF_ENTER
84	// (entry into vsim), matching marker-mode enter-marker semantics.
85	static uint64_t enter_pc_arg;
86	static int pc_mode;
87	
88	// Oracle exit-drain mode (verify_oracle F1): when exit_marker_mode or
89	// exit_pc_mode is set (plugin args `exit_marker=1` / `exit_pc=0x...`), a
90	// pure-QEMU run produces the differential verifier's reference state. Every
91	// insn gets an exec callback: the tick ARMS on the
92	// ROI exit boundary (EXIT marker match, or vaddr == exit_pc) and DRAINS on
93	// the next callback. Exec callbacks fire before their insn executes, so the
94	// armed drain captures "after the boundary insn retired" -- exactly vsim's
95	// exit-drain record (DPC = next insn to execute) -- and reports that next
96	// insn's vaddr as pc, correct even when the boundary insn branches.
97	// Exclusive with the other trigger modes: the oracle run never hands off.
98	//
99	// drain_pc=0x... (optional modifier): drain at the first post-arm tick whose
100	// vaddr equals drain_pc, instead of the very next tick. The differential
101	// harness passes vsim's actual drained pc here: vsim's DMI halt lands a
102	// variable 0-3 insns past the trigger (the core keeps retiring while the
103	// haltreq propagates), and the two states only compare equal when both
104	// sides sample the SAME architectural point. If vsim's pc is never reached
105	// (a real control-flow divergence), the oracle never drains and QEMU runs
106	// to completion -- the caller sees exit != 200.
107	static uint64_t exit_pc_arg;
108	static int      exit_pc_mode;
109	static int      exit_marker_mode;
110	static uint64_t drain_pc_arg;
111	static int      drain_pc_set;
112	static volatile int oracle_armed;
113	
114	static struct qemu_plugin_register *find_reg(GArray *regs, const char *name)
115	{
116	    for (guint i = 0; i < regs->len; i++) {
117	        qemu_plugin_reg_descriptor *rd =
118	            &g_array_index(regs, qemu_plugin_reg_descriptor, i);
119	        if (g_ascii_strcasecmp(rd->name, name) == 0) {
120	            return rd->handle;
121	        }
122	    }
123	    return NULL;
124	}
125	
126	// Lazily resolves register handles. The plugin's vcpu_init runs before
127	// QEMU has registered the dynamic gdb coprocessors (FPU, virtual, csr,
128	// vector), so qemu_plugin_get_registers() returns only the 33 core CPU
129	// regs at that moment. By the time the entry trigger fires, all dynamic
130	// features are registered and a fresh call returns the full list.
131	static void resolve_handles(VcpuRegs *v)
132	{
133	    g_autoptr(GArray) regs = qemu_plugin_get_registers();
134	    for (int i = 0; i < 32; i++) {
135	        v->gpr[i] = find_reg(regs, hybrid_gpr_names[i]);
136	        v->fpr[i] = find_reg(regs, hybrid_fpr_names[i]);
137	    }
138	    v->fcsr = find_reg(regs, "fcsr");
139	    v->pc = find_reg(regs, "pc");
140	    v->priv = find_reg(regs, "priv");
141	
142	    v->mstatus  = find_reg(regs, "mstatus");
143	    v->mepc     = find_reg(regs, "mepc");
144	    v->mtvec    = find_reg(regs, "mtvec");
145	    v->mcause   = find_reg(regs, "mcause");
146	    v->mtval    = find_reg(regs, "mtval");
147	    v->mscratch = find_reg(regs, "mscratch");
148	    v->medeleg  = find_reg(regs, "medeleg");
149	    v->mideleg  = find_reg(regs, "mideleg");
150	    v->mip      = find_reg(regs, "mip");
151	    v->mie      = find_reg(regs, "mie");
152	    v->mcycle   = find_reg(regs, "mcycle");
153	    v->minstret = find_reg(regs, "minstret");
154	    v->satp     = find_reg(regs, "satp");
155	
156	    v->mcache_ctl = find_reg(regs, "mcache_ctl");
157	    v->mmisc_ctl  = find_reg(regs, "mmisc_ctl");
158	
159	    char buf[16];
160	
161	    // Andes V5 CSR block (v3): resolve by gdb mnemonic from the shared X-macro.
162	#define HYBRID_ANDES_FIELD(field, addr, name) v->andes_##field = find_reg(regs, name);
163	    HYBRID_ANDES_CSR_LIST(HYBRID_ANDES_FIELD)
164	#undef HYBRID_ANDES_FIELD
165	    for (int i = 0; i < HYBRID_PMA_CFG_NUM; i++) {
166	        // RV64 packs 8 PMA entries per cfg CSR, so only even cfg CSRs exist.
167	        g_snprintf(buf, sizeof(buf), "pmacfg%d", 2 * i);
168	        v->pmacfg[i] = find_reg(regs, buf);
169	    }
170	    for (int i = 0; i < HYBRID_PMA_ADDR_NUM; i++) {
171	        g_snprintf(buf, sizeof(buf), "pmaaddr%d", i);
172	        v->pmaaddr[i] = find_reg(regs, buf);
173	    }
174	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++) {
175	        g_snprintf(buf, sizeof(buf), "pmpcfg%d", i);
176	        v->pmpcfg[i] = find_reg(regs, buf);
177	    }
178	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++) {
179	        g_snprintf(buf, sizeof(buf), "pmpaddr%d", i);
180	        v->pmpaddr[i] = find_reg(regs, buf);
181	    }
182	
183	    v->vstart = find_reg(regs, "vstart");
184	    v->vxsat  = find_reg(regs, "vxsat");
185	    v->vxrm   = find_reg(regs, "vxrm");
186	    v->vcsr   = find_reg(regs, "vcsr");
187	    v->vtype  = find_reg(regs, "vtype");
188	    v->vl     = find_reg(regs, "vl");
189	    v->vlenb  = find_reg(regs, "vlenb");
190	    for (int i = 0; i < 32; i++) {
191	        g_snprintf(buf, sizeof(buf), "v%d", i);
192	        v->vreg[i] = find_reg(regs, buf);
193	    }
194	}
195	
196	static uint64_t read_reg64(struct qemu_plugin_register *h)
197	{
198	    if (!h) return 0;
199	    g_autoptr(GByteArray) buf = g_byte_array_new();
200	    int sz = qemu_plugin_read_register(h, buf);
201	    if (sz <= 0) return 0;
202	    uint64_t v = 0;
203	    memcpy(&v, buf->data, sz < 8 ? (size_t) sz : 8);
204	    return v;
205	}
206	
207	// Reads up to `dst_max` bytes from a register handle. Returns the byte
208	// count written (0 on failure or NULL handle). Used for vector regs whose
209	// width = vlenb bytes.
210	static size_t read_reg_bytes(struct qemu_plugin_register *h,
211	                             uint8_t *dst, size_t dst_max)
212	{
213	    if (!h || dst_max == 0) return 0;
214	    g_autoptr(GByteArray) buf = g_byte_array_new();
215	    int sz = qemu_plugin_read_register(h, buf);
216	    if (sz <= 0) return 0;
217	    size_t n = (size_t) sz < dst_max ? (size_t) sz : dst_max;
218	    memcpy(dst, buf->data, n);
219	    return n;
220	}
221	
222	// Atomic on POSIX: write to a mkstemp-reserved tmp file, fsync, rename.
223	// mkstemp guarantees uniqueness via a 6-char random suffix + atomic
224	// O_EXCL-style inode reservation, so concurrent plugin instances cannot
225	// collide even under aggressive PID reuse (B13). The tmp lives in the
226	// same directory as `path` so the rename is intra-filesystem.
227	static int write_state_atomic(const struct hybrid_state_v1 *s, const char *path)
228	{
229	    char tmp[PATH_MAX];
230	    int n = g_snprintf(tmp, sizeof(tmp), "%s.tmp.XXXXXX", path);
231	    if (n < 0 || (size_t) n >= sizeof(tmp)) {
232	        fprintf(stderr, "hybrid_handoff: tmp path too long\n");
233	        return -1;
234	    }
235	    int fd = g_mkstemp(tmp);
236	    if (fd < 0) {
237	        perror("hybrid_handoff: g_mkstemp");
238	        return -1;
239	    }
240	    // g_mkstemp creates the file 0600; no further chmod needed.
241	    ssize_t want = (ssize_t) sizeof(*s);
242	    ssize_t got = write(fd, s, sizeof(*s));
243	    if (got != want) {
244	        perror("hybrid_handoff: write");
245	        close(fd);
246	        unlink(tmp);
247	        return -1;
248	    }
249	    fsync(fd);
250	    close(fd);
251	    if (rename(tmp, path) != 0) {
252	        perror("hybrid_handoff: rename");
253	        unlink(tmp);
254	        return -1;
255	    }
256	    return 0;
257	}
258	
259	// Drain CPU state into `*s`. pc is computed by the caller (from a
260	// HandoffSite for trigger paths). If minstret_override is non-zero, it
261	// replaces QEMU's PMU minstret.
262	static void drain_state_into(unsigned int vcpu_idx, uint64_t pc,
263	                             uint64_t minstret_override,
264	                             struct hybrid_state_v1 *sp)
265	{
266	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
267	    resolve_handles(v);
268	    memset(sp, 0, sizeof(*sp));
269	    struct hybrid_state_v1 s = {0};
270	    s.magic   = HYBRID_STATE_MAGIC;
271	    s.version = HYBRID_STATE_VERSION;
272	    s.flags   = HYBRID_FLAG_RV64;
273	    s.hart_id = vcpu_idx;
274	    // L6: real privilege at the boundary; M-mode fallback only when the
275	    // stub doesn't advertise the gdbstub virtual feature (a missing handle
276	    // reads as 0 = U, which would silently demote the hart).
277	    s.priv    = v->priv ? (read_reg64(v->priv) & 0x3) : 3;
278	    s.pc      = pc;
279	    for (int i = 0; i < 32; i++) s.gpr[i] = read_reg64(v->gpr[i]);
280	
281	    // Floating-point: only set FP flag if at least one handle was bound,
282	    // i.e. QEMU advertised the FPU feature (D extension).
283	    int has_fp = 0;
284	    for (int i = 0; i < 32; i++) {
285	        s.fpr[i] = read_reg64(v->fpr[i]);
286	        if (v->fpr[i]) has_fp = 1;
287	    }
288	    if (has_fp) s.flags |= HYBRID_FLAG_FP;
289	    s.fcsr = read_reg64(v->fcsr);  // L20: rides HYBRID_FLAG_FP
290	
291	    s.mstatus  = read_reg64(v->mstatus);
292	    s.mepc     = read_reg64(v->mepc);
293	    s.mtvec    = read_reg64(v->mtvec);
294	    s.mcause   = read_reg64(v->mcause);
295	    s.mtval    = read_reg64(v->mtval);
296	    s.mscratch = read_reg64(v->mscratch);
297	    s.medeleg  = read_reg64(v->medeleg);
298	    s.mideleg  = read_reg64(v->mideleg);
299	    s.mip      = read_reg64(v->mip);
300	    s.mie      = read_reg64(v->mie);
301	    s.mcycle   = read_reg64(v->mcycle);
302	    s.minstret = minstret_override ? minstret_override
303	                                   : read_reg64(v->minstret);
304	    s.satp     = read_reg64(v->satp);
305	
306	    // Andes cache fix: carry crt0's cache-enable so the cycle engine resumes
307	    // with caches on (NULL handle on a non-Andes stub reads back as 0).
308	    s.mcache_ctl = read_reg64(v->mcache_ctl);
309	    s.mmisc_ctl  = read_reg64(v->mmisc_ctl);
310	
311	    // Andes V5 CSR block (v3): drain every transported Andes CSR. Set
312	    // HYBRID_FLAG_ANDES if the stub advertised at least one (mirrors has_fp/
313	    // has_v); otherwise the block stays zero and consumers skip it. A NULL
314	    // handle on a non-Andes stub reads back as 0 -> tolerant.
315	    int has_andes = 0;
316	#define HYBRID_ANDES_FIELD(field, addr, name)  \
317	    s.andes.field = read_reg64(v->andes_##field); \
318	    if (v->andes_##field) has_andes = 1;
319	    HYBRID_ANDES_CSR_LIST(HYBRID_ANDES_FIELD)
320	#undef HYBRID_ANDES_FIELD
321	    for (int i = 0; i < HYBRID_PMA_CFG_NUM; i++) {
322	        s.andes.pmacfg[i] = read_reg64(v->pmacfg[i]);
323	        if (v->pmacfg[i]) has_andes = 1;
324	    }
325	    for (int i = 0; i < HYBRID_PMA_ADDR_NUM; i++) {
326	        s.andes.pmaaddr[i] = read_reg64(v->pmaaddr[i]);
327	        if (v->pmaaddr[i]) has_andes = 1;
328	    }
329	    if (has_andes) s.flags |= HYBRID_FLAG_ANDES;
330	
331	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++)
332	        s.pmpcfg[i] = read_reg64(v->pmpcfg[i]);
333	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++)
334	        s.pmpaddr[i] = read_reg64(v->pmpaddr[i]);
335	
336	    // Vector: only set V flag if QEMU advertised the V extension. vlenb
337	    // bounds the per-register byte count copied into vreg[]. The policy
338	    // helper (hybrid_v_drain_policy) decides SKIP/OK/ABORT from the
339	    // handle truthiness so we don't conflate "stub missing vlenb" with
340	    // "V disabled at runtime"; see include/hybrid/v_drain_policy.h.
341	    s.vstart = read_reg64(v->vstart);
342	    s.vxsat  = read_reg64(v->vxsat);
343	    s.vxrm   = read_reg64(v->vxrm);
344	    s.vcsr   = read_reg64(v->vcsr);
345	    s.vtype  = read_reg64(v->vtype);
346	    s.vl     = read_reg64(v->vl);
347	    s.vlenb  = read_reg64(v->vlenb);
348	    int has_other_v = (v->vstart || v->vxsat || v->vxrm || v->vcsr
349	                       || v->vtype || v->vl);
350	    if (!has_other_v) {
351	        for (int i = 0; i < 32; i++)
352	            if (v->vreg[i]) { has_other_v = 1; break; }
353	    }
354	    HybridVDrainPolicy vpol = hybrid_v_drain_policy(
355	        v->vlenb != NULL, has_other_v, s.vlenb);
356	    if (vpol == HYBRID_V_DRAIN_ABORT) {
357	        if (v->vlenb == NULL)
358	            fprintf(stderr,
359	                    "hybrid_handoff: stub advertised V CSRs/regs but not "
360	                    "vlenb; refusing to drain partial V state\n");
361	        else
362	            fprintf(stderr,
363	                    "hybrid_handoff: vlenb=%" PRIu64 " exceeds the wire-format "
364	                    "ceiling HYBRID_VLEN_BYTES_MAX=%d (VLEN %d); refusing to "
365	                    "truncate V registers\n",
366	                    s.vlenb, HYBRID_VLEN_BYTES_MAX,
367	                    8 * HYBRID_VLEN_BYTES_MAX);
368	        exit(2);
369	    }
370	    if (vpol == HYBRID_V_DRAIN_OK) {
371	        s.flags |= HYBRID_FLAG_V;
372	        /* The policy guarantees vlenb <= HYBRID_VLEN_BYTES_MAX here, so the
373	         * full live register fits the wire-format slot -- no clamp (L11). */
374	        for (int i = 0; i < 32; i++)
375	            (void) read_reg_bytes(v->vreg[i],
376	                                  &s.vreg[(size_t) i * HYBRID_VLEN_BYTES_MAX],
377	                                  (size_t) s.vlenb);
378	    }
379	
380	    *sp = s;
381	}
382	
383	// Drain CPU state to `path`. Does NOT call exit -- the caller decides
384	// exit(200).
385	static void drain_state_to_file(unsigned int vcpu_idx, uint64_t pc,
386	                                uint64_t minstret_override, const char *path)
387	{
388	    struct hybrid_state_v1 s;
389	    drain_state_into(vcpu_idx, pc, minstret_override, &s);
390	    if (write_state_atomic(&s, path) != 0) {
391	        fprintf(stderr, "hybrid_handoff: failed to write state file\n");
392	        exit(2);
393	    }
394	    fprintf(stderr,
395	            "hybrid_handoff: drained state to %s (pc=%#" PRIx64 ")\n",
396	            path, s.pc);
397	}
398	
399	// Shared drain tail: capture the (pre-execution) state, report `resume_pc`
400	// as the vsim resume point, and exit 200.
401	static void handoff_drain(unsigned int vcpu_idx, uint64_t resume_pc)
402	{
403	    drain_state_to_file(vcpu_idx, resume_pc, 0, outfile_path);
404	    // 200 == kExitHandoffToQemu in verilator/src/hybrid/exit_codes.hpp.
405	    // Distinguishes drain from workload completion (0) so the orchestrator
406	    // can decide the next spawn.
407	    exit(200);
408	}
409	
410	// Marker sites. The marker is an architectural NOP, so the pre-execution
411	// state equals the post-retire state and the window resumes AFTER it
412	// (vaddr+size, computed at translation time; reading the gdbstub PC inside
413	// the exec callback can lag the actual current insn when V instructions
414	// retire just before the trigger -- TCG defers PC writes for performance).
415	static void on_handoff(unsigned int vcpu_idx, void *udata)
416	{
417	    const HandoffSite *site = (const HandoffSite *) udata;
418	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
419	    handoff_drain(vcpu_idx, compute_handoff_pc(site));
420	}
421	
422	// pc boundary sites. Exec callbacks fire BEFORE the insn
423	// executes, and the boundary insn is real user code (unlike a marker NOP):
424	// the drained state must resume AT the boundary so the insn executes inside
425	// the vsim window rather than on neither leg. (Skipping it corrupts the
426	// window's architectural state -- e.g. a skipped vsetivli leaves vtype.vill
427	// set and the first vector op of the window faults.)
428	static void on_handoff_boundary(unsigned int vcpu_idx, void *udata)
429	{
430	    const HandoffSite *site = (const HandoffSite *) udata;
431	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
432	    handoff_drain(vcpu_idx, site->vaddr);
433	}
434	
435	// Per-insn tick for oracle exit-drain mode. udata is this insn's HandoffSite.
436	// When armed (the exit boundary's own tick ran), this tick fires before its
437	// insn executes, so a drain here records the post-retire state of the
438	// boundary insn with pc = the dynamically-next insn's vaddr.
439	static void on_oracle_tick(unsigned int vcpu_idx, void *udata)
440	{
441	    const HandoffSite *site = (const HandoffSite *) udata;
442	    if (oracle_armed
443	        && (!drain_pc_set || site->vaddr == drain_pc_arg)) {
444	        handoff_drain(vcpu_idx, site->vaddr);
445	    }
446	    if (exit_pc_mode ? (site->vaddr == exit_pc_arg)
447	                     : (site->kind == HYBRID_HANDOFF_EXIT)) {
448	        oracle_armed = 1;
449	    }
450	}
451	
452	static void vcpu_tb_trans(qemu_plugin_id_t id, struct qemu_plugin_tb *tb)
453	{
454	    (void) id;
455	    size_t n = qemu_plugin_tb_n_insns(tb);
456	
457	    for (size_t i = 0; i < n; i++) {
458	        struct qemu_plugin_insn *insn = qemu_plugin_tb_get_insn(tb, i);
459	
460	        // Oracle exit-drain mode: exclusive with every other mode (enforced
461	        // at install), so it owns the insn's registration outright. The site
462	        // carries the marker kind so the tick can arm on the EXIT marker.
463	        if (exit_marker_mode || exit_pc_mode) {
464	            HandoffSite *site = g_new0(HandoffSite, 1);
465	            site->kind  = HYBRID_HANDOFF_NONE;
466	            site->vaddr = qemu_plugin_insn_vaddr(insn);
467	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
468	            if (exit_marker_mode && site->size == 4) {
469	                uint32_t raw = 0;
470	                if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) == sizeof(raw))
471	                    hybrid_match_handoff_insn(raw, &site->kind);
472	            }
473	            qemu_plugin_register_vcpu_insn_exec_cb(
474	                insn, on_oracle_tick, QEMU_PLUGIN_CB_R_REGS, site);
475	            continue;
476	        }
477	
478	        if (pc_mode) {
479	            // PC-trigger mode: vaddr-only match; the drain resumes AT the
480	            // boundary (on_handoff_boundary), so the insn size is recorded
481	            // only for completeness.
482	            if (qemu_plugin_insn_vaddr(insn) != enter_pc_arg) continue;
483	            HandoffSite *site = g_new0(HandoffSite, 1);
484	            site->kind  = HYBRID_HANDOFF_ENTER;
485	            site->vaddr = qemu_plugin_insn_vaddr(insn);
486	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
487	            qemu_plugin_register_vcpu_insn_exec_cb(
488	                insn, on_handoff_boundary, QEMU_PLUGIN_CB_R_REGS, site);
489	            continue;
490	        }
491	
492	        // Marker-trigger mode (default).
493	        // The markers are `slti x0, x0, 0x5A0/0x5A1`, always 32-bit
494	        // (sz==4): SLTI has no compressed form, so the sz!=4 skip is
495	        // exact, not an approximation.
496	        size_t sz = qemu_plugin_insn_size(insn);
497	        if (sz != 4) continue;
498	        uint32_t raw = 0;
499	        if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) != sizeof(raw))
500	            continue;
501	        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
502	        if (!hybrid_match_handoff_insn(raw, &kind)) continue;
503	        HandoffSite *site = g_new0(HandoffSite, 1);
504	        site->kind  = kind;
505	        site->vaddr = qemu_plugin_insn_vaddr(insn);
506	        site->size  = (uint32_t) sz;
507	        qemu_plugin_register_vcpu_insn_exec_cb(
508	            insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
509	    }
510	}
511	
512	QEMU_PLUGIN_EXPORT int qemu_plugin_install(qemu_plugin_id_t id,
513	                                           const qemu_info_t *info,
514	                                           int argc, char **argv)
515	{
516	    (void) info;
517	    for (int i = 0; i < argc; i++) {
518	        g_auto(GStrv) tok = g_strsplit(argv[i], "=", 2);
519	        if (g_strcmp0(tok[0], "outfile") == 0 && tok[1]) {
520	            outfile_path = g_strdup(tok[1]);
521	        } else if (g_strcmp0(tok[0], "enter_pc") == 0 && tok[1]) {
522	            char *endp = NULL;
523	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
524	            if (!endp || *endp != '\0') {
525	                fprintf(stderr, "hybrid_handoff: invalid enter_pc=%s\n",
526	                        tok[1]);
527	                return -1;
528	            }
529	            enter_pc_arg = (uint64_t) v;
530	            pc_mode = 1;
531	        } else if (g_strcmp0(tok[0], "exit_pc") == 0 && tok[1]) {
532	            char *endp = NULL;
533	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
534	            if (!endp || *endp != '\0') {
535	                fprintf(stderr, "hybrid_handoff: invalid exit_pc=%s\n",
536	                        tok[1]);
537	                return -1;
538	            }
539	            exit_pc_arg = (uint64_t) v;
540	            exit_pc_mode = 1;
541	        } else if (g_strcmp0(tok[0], "exit_marker") == 0 && tok[1]) {
542	            char *endp = NULL;
543	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
544	            if (!endp || *endp != '\0') {
545	                fprintf(stderr, "hybrid_handoff: invalid exit_marker=%s\n",
546	                        tok[1]);
547	                return -1;
548	            }
549	            exit_marker_mode = (v != 0);
550	        } else if (g_strcmp0(tok[0], "drain_pc") == 0 && tok[1]) {
551	            char *endp = NULL;
552	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
553	            if (!endp || *endp != '\0') {
554	                fprintf(stderr, "hybrid_handoff: invalid drain_pc=%s\n",
555	                        tok[1]);
556	                return -1;
557	            }
558	            drain_pc_arg = (uint64_t) v;
559	            drain_pc_set = 1;
560	        } else {
561	            fprintf(stderr, "hybrid_handoff: unknown option: %s\n", argv[i]);
562	            return -1;
563	        }
564	    }
565	    if (!outfile_path) {
566	        fputs("hybrid_handoff: outfile=PATH is required\n", stderr);
567	        return -1;
568	    }
569	    if (pc_mode) {
570	        fprintf(stderr,
571	                "hybrid_handoff: PC-mode enter=0x%" PRIx64 "\n",
572	                enter_pc_arg);
573	    }
574	    if (exit_marker_mode || exit_pc_mode) {
575	        if ((exit_marker_mode && exit_pc_mode) || pc_mode) {
576	            fputs("hybrid_handoff: oracle exit drain (exit_marker/exit_pc) "
577	                  "is exclusive with the other trigger modes\n", stderr);
578	            return -1;
579	        }
580	        if (exit_pc_mode) {
581	            fprintf(stderr,
582	                    "hybrid_handoff: oracle exit-drain mode exit_pc=0x%"
583	                    PRIx64 "\n", exit_pc_arg);
584	        } else {
585	            fputs("hybrid_handoff: oracle exit-drain mode (exit marker)\n",
586	                  stderr);
587	        }
588	        if (drain_pc_set) {
589	            fprintf(stderr, "hybrid_handoff: oracle drain_pc=0x%" PRIx64 "\n",
590	                    drain_pc_arg);
591	        }
592	    } else if (drain_pc_set) {
593	        fputs("hybrid_handoff: drain_pc requires oracle exit-drain mode "
594	              "(exit_marker/exit_pc)\n", stderr);
595	        return -1;
596	    }
597	
598	    vcpu_state = qemu_plugin_scoreboard_new(sizeof(VcpuRegs));
599	    qemu_plugin_register_vcpu_tb_trans_cb(id, vcpu_tb_trans);
600	    return 0;
601	}
